using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class HostageCustodyTests
{
    static readonly EntityId Player=new("person:shingen"),Ward=new("created:ward"),ReceiverHouse=new("org:oda");
    static WorldSession Start(ulong seed=42,bool on=true,bool minor=false,bool local=true){var p=NewGameWorldTests.Officer(Ward.Value,StartTemplate.Retainer,lord:Player.Value) with{BirthYear=minor?1550:1520};var setup=NewGameWorldTests.Setup([p]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,Player.Value,seed,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy,socialPolicy:CharacterRelations.Policy,adoptionPolicy:AdultAdoption.Policy,marriagePolicy:AdultMarriage.Policy,custodyPolicy:on?HostageCustody.Policy:null));if(local)Move(s,"castle");return s;}
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:custody-trip/"+s.Revision,node),s.Revision));At(s,s.Seconds+2);At(s,s.GetBranchView(s.PlayerControl).ArrivalAt!.Value+1);}
    static readonly Lazy<ulong> Yes=new(()=>Find(true)),No=new(()=>Find(false));
    static ulong Find(bool yes){for(ulong n=1;n<100;n++){var w=Start(n,local:false).DiagnosticSnapshot();if((CharacterRelations.DiagnosticTrait(w,Ward,SocialTrait.Duty)+CharacterRelations.DiagnosticTrait(w,Ward,SocialTrait.Affection)>=80)==yes)return n;}throw new Exception("Missing response fixture");}
    static CommandResult Act(WorldSession s,CustodyAction action,EntityId? root=null,string? id=null)=>s.ManageCustody(new(new(id??"request:custody/"+s.Revision),action,action==CustodyAction.Propose?Ward:null,action==CustodyAction.Propose?ReceiverHouse:null,root,action==CustodyAction.Propose?1:0,action==CustodyAction.Propose?"現地での安全な預かりと一日以内の返還":null),s.PlayerControl,s.Revision);
    static EntityId Propose(WorldSession s){Good(Act(s,CustodyAction.Propose));return s.DiagnosticSnapshot().Custody!.Entries.Last().Input.Id;}
    static WorldSession Agreed(){var s=Start(Yes.Value);Propose(s);At(s,s.Seconds+1);Assert.Single(s.DiagnosticSnapshot().Custody!.Entries,e=>e.Input.Action==CustodyAction.PersonalAccept);Assert.Single(s.DiagnosticSnapshot().Custody!.Entries,e=>e.Input.Action==CustodyAction.ReceiverAccept);return s;}
    static WorldSession Held(){var s=Agreed();Good(Act(s,CustodyAction.Admit,s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id));return s;}
    [Fact]public void OldPolicyStaysAbsent(){var s=Start(on:false);Assert.Null(s.DiagnosticSnapshot().Custody);Assert.DoesNotContain("CustodyPolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot())));Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Propose).Code);}
    [Fact]public void PersonalAndReceiverAgreementDoNotAdmitAutomatically(){var s=Agreed();Assert.False(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));Assert.True(HostageCustody.View(s.DiagnosticSnapshot()).Single().CanAdmit);}
    [Fact]public void ActualAdmissionKeepsIdentityLocationLifeAndLegalRights(){var s=Agreed();var before=s.DiagnosticSnapshot();Good(Act(s,CustodyAction.Admit,before.Custody!.Entries.First().Input.Id));var w=s.DiagnosticSnapshot();Assert.True(HostageCustody.HeldAt(w,Ward,s.Seconds,s.Revision+1));Assert.Equal(ContractJson.Write(before.Characters),ContractJson.Write(w.Characters));Assert.Equal(ContractJson.Write(before.Locations),ContractJson.Write(w.Locations));Assert.Equal(ContractJson.Write(before.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(before.Offices),ContractJson.Write(w.Offices));Assert.Equal(ContractJson.Write(before.LandRights),ContractJson.Write(w.LandRights));Assert.Equal(NewGameWork.Balance(before,Ward),NewGameWork.Balance(w,Ward));}
    [Fact]public void HeldPersonCannotAcceptOrdinaryWorkOrMovement(){var s=Held();foreach(var i in new[]{NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:held-inspect"),TravelWorld.Move(s.DiagnosticSnapshot(),"request:held-move","fork")})Assert.NotEqual(ResultCode.Accepted,s.Submit(i with{Actor=Ward,Executor=Ward},s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(new(new("request:held-companion"),Ward,CompanionAction.Agree,20),Player,s.Revision).Code);Assert.DoesNotContain(Ward,AdultAdoption.Candidates(s.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ReleaseIsLocalAndRestoresAvailabilityWithoutTeleport(){var s=Held();var root=s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id;var before=s.DiagnosticSnapshot().Locations;Good(Act(s,CustodyAction.Release,root));Assert.False(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));Assert.Equal(ContractJson.Write(before),ContractJson.Write(s.DiagnosticSnapshot().Locations));Assert.Contains(Ward,AdultAdoption.Candidates(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Release,root).Code);}
    [Fact]public void RefusalCannotBeOverridden(){var s=Start(No.Value);var root=Propose(s);At(s,s.Seconds+1);Assert.Single(s.DiagnosticSnapshot().Custody!.Entries,e=>e.Input.Action==CustodyAction.PersonalRefuse);Assert.DoesNotContain(s.DiagnosticSnapshot().Custody!.Entries,e=>e.Input.Action==CustodyAction.ReceiverAccept);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Admit,root).Code);}
    [Fact]public void WithdrawalBeforeAnswerLeavesNoCustody(){var s=Start(Yes.Value);var root=Propose(s);Good(Act(s,CustodyAction.Withdraw,root));At(s,s.Seconds+2);Assert.Equal(2,s.DiagnosticSnapshot().Custody!.Entries.Length);Assert.False(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));}
    [Fact]public void OverduePersonIsNotDeletedExecutedOrAutomaticallyReturned(){var s=Held();var terms=s.DiagnosticSnapshot().Custody!.Entries.First().Terms!;At(s,terms.Until+1);Assert.True(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));Assert.Contains("期限超過",HostageCustody.View(s.DiagnosticSnapshot()).Single().Status);Assert.Equal(LifeState.Adult,s.DiagnosticSnapshot().Characters.Single(c=>c.Id==Ward).Life);Good(Act(s,CustodyAction.Release,terms.Id));}
    [Fact]public void ExpiredPendingProposalCannotAdmit(){var s=Agreed();var t=s.DiagnosticSnapshot().Custody!.Entries.First().Terms!;At(s,t.Until+1);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Admit,t.Id).Code);}
    [Theory][InlineData(true,true)][InlineData(false,false)]public void MinorOrAbsentGuardianCannotPropose(bool minor,bool local){var s=Start(Yes.Value,minor:minor,local:local);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Propose).Code);}
    [Fact]public void AlreadyPromisedPersonCannotBeOfferedAgain(){var s=Start(Yes.Value);Propose(s);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Propose).Code);}
    [Fact]public void PendingFamilyUndertakingBlocksAdmissionProposal(){var s=Start(Yes.Value);Good(s.DecideAdoption(new(new("request:custody-family"),AdoptionAction.Propose,Ward),Player,s.Revision));Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Propose).Code);}
    [Fact]public void CannotImpersonatePersonalOrReceiverResponse(){var s=Start(Yes.Value);var root=Propose(s);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.PersonalAccept,root).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.ReceiverAccept,root).Code);}
    [Fact]public void RetryIsIdempotentAndPayloadConflictIsRejected(){var s=Start(Yes.Value);var root=Propose(s);Assert.Equal(ResultCode.AlreadyAccepted,Act(s,CustodyAction.Propose,id:root.Value).Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,CustodyAction.Withdraw,root,id:root.Value).Code);Assert.Single(s.DiagnosticSnapshot().Custody!.Entries);}
    [Fact]public void LeavingDoesNotMoveWardAndRemoteReleaseIsRejected(){var s=Held();var root=s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id;Move(s,"fork");Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Release,root).Code);Assert.False(HostageCustody.View(s.DiagnosticSnapshot()).Single().CanRelease);Assert.Equal(new EntityId("site:castle"),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Ward).Site);}
    [Fact]public void ForgedAdmissionWithoutConsentCannotLoad(){var s=Start(Yes.Value);var root=Propose(s);var w=s.DiagnosticSnapshot();w.Custody=w.Custody! with{Entries=[..w.Custody.Entries,new(new(new("request:fake-custody"),CustodyAction.Admit,Original:root),Player,s.Seconds,s.Revision,null)]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]public void ActualGenerationRecoveryPreservesCustodyAndFuture(int phase){var s=Start(phase==4?No.Value:Yes.Value);var root=Propose(s);if(phase>0)At(s,s.Seconds+1);if(phase is 2 or 3)Good(Act(s,CustodyAction.Admit,root));if(phase==3)Good(Act(s,CustodyAction.Release,root));if(phase==5)Good(Act(s,CustodyAction.Withdraw,root));s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"custody-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"custody",w.WorldId).Published);var host=new WorldSessionHost(Start(local:false));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("custody"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(HostageCustody.View(w)),ContractJson.Write(HostageCustody.View(host.Current.DiagnosticSnapshot())));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"hostage-custody-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"hostage-custody-"+phase+".restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}

    [Fact]public void ReceiverRefusalCannotBeOverriddenByGuardian(){var original=Start(Yes.Value).DiagnosticSnapshot();original.Characters=original.Characters.Select(c=>c.Id==new EntityId("person:nobunaga")?c with{WillObey=false}:c).ToArray();var s=new WorldSession(original);var root=Propose(s);At(s,s.Seconds+1);Assert.Single(s.DiagnosticSnapshot().Custody!.Entries,e=>e.Input.Action==CustodyAction.ReceiverRefuse);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Admit,root).Code);}
    [Fact]public void ActualPendingWorkMustFinishBeforeOfferingTheSamePerson(){ulong seed=0;for(ulong n=1;n<100;n++){if(CharacterRelations.AcceptsCompanion(Start(n,local:false).DiagnosticSnapshot(),Ward,20,0,1)){seed=n;break;}}Assert.True(seed>0);var s=Start(seed);Good(s.ManageCompanion(new(new("request:busy-agree"),Ward,CompanionAction.Agree,20),Player,s.Revision));Good(s.ManageCompanion(new(new("request:busy-inspect"),Ward,CompanionAction.Inspect),Player,s.Revision));Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Propose).Code);At(s,s.Seconds+10);Good(s.ManageCompanion(new(new("request:busy-end"),Ward,CompanionAction.EndAgreement),Player,s.Revision));Propose(s);}
    [Fact]public void ActiveCompanionUndertakingBlocksGuarantee(){ulong seed=0;for(ulong n=1;n<100;n++){var w=Start(n,local:false).DiagnosticSnapshot();if(CharacterRelations.AcceptsCompanion(w,Ward,20,0,1)){seed=n;break;}}Assert.True(seed>0);var s=Start(seed);Good(s.ManageCompanion(new(new("request:companion-before-custody"),Ward,CompanionAction.Agree,20),Player,s.Revision));Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Propose).Code);}
    [Fact]public void ReleasedPersonCanEnterANewIndependentGuarantee(){var s=Held();var old=s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id;Good(Act(s,CustodyAction.Release,old));var fresh=Propose(s);Assert.NotEqual(old,fresh);At(s,s.Seconds+1);Good(Act(s,CustodyAction.Admit,fresh));Assert.True(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void StaleRequestDoesNotCommitAndIdsCannotBecomeTasks(){var s=Start(Yes.Value);var input=new CustodyInput(new("request:custody-stale"),CustodyAction.Propose,Ward,ReceiverHouse,Days:1,Guarantee:"返還の保証");Assert.Equal(ResultCode.StateChanged,s.ManageCustody(input,Player,s.Revision+1).Code);var root=Propose(s);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),root.Value),s.Revision).Code);}
}
